from typing import Dict, Any
from .models import EventPlan

def generate_markdown_dossier(plan: EventPlan) -> str:
    req = plan.event_request
    curr = req.currency

    md = f"""# {req.title} — Event Planning Dossier
**Generated by EventGenie AI**

## Overview
- **Event Type:** {req.event_type}
- **Location:** {req.city_or_location}
- **Date:** {req.event_date}
- **Guests:** {req.guest_count} attendees
- **Total Budget:** {curr}{plan.total_budget:,.2f}
- **Cost Per Guest:** {curr}{plan.cost_per_guest:,.2f}
- **Theme:** {plan.personalized_ideas.theme_title}

---

## 1. Budget Breakdown & Allocations
Total Allocated: {curr}{plan.total_allocated:,.2f} | Contingency Reserve: {curr}{plan.contingency_fund:,.2f}

| Category | Allocated ({curr}) | % of Budget | Cost / Guest ({curr}) | Priority | Cost Saving Lever |
| :--- | :--- | :--- | :--- | :--- | :--- |
"""
    for cat in plan.budget_categories:
        md += f"| **{cat.name}** | {curr}{cat.allocated_amount:,.2f} | {cat.percentage}% | {curr}{cat.per_guest_cost:,.2f} | {cat.priority} | {cat.cost_saving_tip} |\n"

    md += "\n### Category Sub-Item Estimates\n"
    for cat in plan.budget_categories:
        md += f"\n#### {cat.name}\n"
        for sub in cat.suggested_subitems:
            md += f"- **{sub.name}:** {curr}{sub.estimated_cost:,.2f} — *{sub.tip or ''}*\n"

    md += f"""
---

## 2. Preparation Timeline & Checklist
"""
    for task in plan.timeline_tasks:
        status_box = "[x]" if task.completed else "[ ]"
        md += f"- {status_box} **{task.title}** ({task.timeframe} — Deadline: {task.estimated_deadline}) `[{task.priority} Priority]`\n"

    md += f"""
---

## 3. Vendor Criteria & Evaluation Checklist
"""
    for v in plan.vendor_checklist:
        md += f"""### {v.category}
- **Typical Cost Range:** {v.typical_cost_range}
- **Key Requirements:**
"""
        for req_item in v.requirements:
            md += f"  - {req_item}\n"
        md += "- **Questions to Ask:**\n"
        for q in v.questions_to_ask:
            md += f"  - \"{q}\"\n"
        md += f"- **Cautionary Advice:** {v.cautionary_advice}\n\n"

    md += f"""
---

## 4. Personalized Styling & Menu
- **Theme Concept:** {plan.personalized_ideas.theme_description}

### Curated Menu
"""
    for course, items in plan.personalized_ideas.curated_menu.items():
        md += f"**{course}:**\n"
        for item in items:
            md += f"- {item}\n"

    md += "\n### Invitation Wording Templates\n"
    for style, text in plan.personalized_ideas.invitation_wordings.items():
        md += f"#### {style}\n> {text}\n\n"

    md += """
---

## Disclosures & Assumptions
"""
    for d in plan.assumptions_and_disclosures:
        md += f"- {d}\n"

    return md

def generate_html_print_dossier(plan: EventPlan) -> str:
    req = plan.event_request
    curr = req.currency

    cat_rows = "".join([
        f"""<tr>
            <td style="padding: 10px; border-bottom: 1px solid #e5e7eb; font-weight: 600;">{c.name}</td>
            <td style="padding: 10px; border-bottom: 1px solid #e5e7eb; text-align: right;">{curr}{c.allocated_amount:,.2f}</td>
            <td style="padding: 10px; border-bottom: 1px solid #e5e7eb; text-align: center;">{c.percentage}%</td>
            <td style="padding: 10px; border-bottom: 1px solid #e5e7eb; text-align: right;">{curr}{c.per_guest_cost:,.2f}</td>
            <td style="padding: 10px; border-bottom: 1px solid #e5e7eb; font-size: 13px; color: #4b5563;">{c.cost_saving_tip}</td>
        </tr>""" for c in plan.budget_categories
    ])

    task_rows = "".join([
        f"""<li style="margin-bottom: 8px;">
            <span style="display: inline-block; width: 18px; height: 18px; border: 2px solid #9ca3af; border-radius: 4px; vertical-align: middle; margin-right: 8px; {'background: #10b981; border-color: #10b981;' if t.completed else ''}"></span>
            <strong>{t.title}</strong> — <span style="color: #6b7280;">{t.timeframe} (Due: {t.estimated_deadline})</span>
            <span style="font-size: 12px; background: #f3f4f6; padding: 2px 6px; border-radius: 4px; margin-left: 6px;">{t.priority}</span>
        </li>""" for t in plan.timeline_tasks
    ])

    vendor_cards = "".join([
        f"""<div style="background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 14px; margin-bottom: 12px;">
            <h4 style="margin: 0 0 6px 0; color: #1e3a8a;">{v.category} <span style="font-size: 13px; font-weight: normal; color: #4b5563;">({v.typical_cost_range})</span></h4>
            <p style="margin: 4px 0; font-size: 13px;"><strong>Watch Out:</strong> {v.cautionary_advice}</p>
        </div>""" for v in plan.vendor_checklist
    ])

    return f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>{req.title} — EventGenie AI Dossier</title>
    <style>
        body {{ font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: #111827; margin: 40px; line-height: 1.5; }}
        h1 {{ color: #1e3a8a; margin-bottom: 4px; }}
        .header-meta {{ color: #6b7280; font-size: 14px; margin-bottom: 24px; border-bottom: 2px solid #e5e7eb; padding-bottom: 12px; }}
        .stats-grid {{ display: flex; gap: 16px; margin-bottom: 24px; }}
        .stat-card {{ flex: 1; background: #f3f4f6; border-radius: 8px; padding: 12px 16px; }}
        .stat-val {{ font-size: 20px; font-weight: bold; color: #1e3a8a; }}
        .stat-lbl {{ font-size: 12px; color: #6b7280; text-transform: uppercase; }}
        table {{ width: 100%; border-collapse: collapse; margin-bottom: 30px; font-size: 14px; }}
        th {{ background: #1e3a8a; color: white; padding: 10px; text-align: left; }}
        h2 {{ color: #1f2937; border-bottom: 1px solid #e5e7eb; padding-bottom: 6px; margin-top: 32px; }}
        @media print {{
            body {{ margin: 15mm; }}
            .no-print {{ display: none; }}
        }}
    </style>
</head>
<body>
    <div class="no-print" style="margin-bottom: 20px; text-align: right;">
        <button onclick="window.print()" style="background: #2563eb; color: white; border: none; padding: 8px 18px; border-radius: 6px; cursor: pointer; font-size: 14px; font-weight: bold;">Print / Save as PDF</button>
    </div>
    <h1>{req.title}</h1>
    <div class="header-meta">
        {req.event_type} &bull; {req.city_or_location} &bull; {req.event_date} &bull; Generated by EventGenie AI
    </div>
    
    <div class="stats-grid">
        <div class="stat-card">
            <div class="stat-lbl">Total Budget</div>
            <div class="stat-val">{curr}{plan.total_budget:,.2f}</div>
        </div>
        <div class="stat-card">
            <div class="stat-lbl">Guest Count</div>
            <div class="stat-val">{req.guest_count}</div>
        </div>
        <div class="stat-card">
            <div class="stat-lbl">Per-Guest Allocation</div>
            <div class="stat-val">{curr}{plan.cost_per_guest:,.2f}</div>
        </div>
        <div class="stat-card">
            <div class="stat-lbl">Contingency Reserve</div>
            <div class="stat-val">{curr}{plan.contingency_fund:,.2f}</div>
        </div>
    </div>

    <h2>1. Smart Budget Breakdown</h2>
    <table>
        <thead>
            <tr>
                <th>Category</th>
                <th style="text-align: right;">Allocated</th>
                <th style="text-align: center;">%</th>
                <th style="text-align: right;">Cost/Guest</th>
                <th>Optimization Strategy</th>
            </tr>
        </thead>
        <tbody>
            {cat_rows}
        </tbody>
    </table>

    <h2>2. Action Timeline & Checklist</h2>
    <ul style="list-style: none; padding-left: 0;">
        {task_rows}
    </ul>

    <h2>3. Vendor Selection & Due Diligence</h2>
    {vendor_cards}

    <h2>4. Creative Styling & Theme: {plan.personalized_ideas.theme_title}</h2>
    <p>{plan.personalized_ideas.theme_description}</p>

    <div style="margin-top: 40px; font-size: 12px; color: #9ca3af; border-top: 1px solid #e5e7eb; padding-top: 10px;">
        EventGenie AI &bull; Intelligent Event Architect &bull; Programmatic Financial Modeling &bull; {plan.created_at}
    </div>
</body>
</html>"""
